#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# Release keys are secrets of the protected `release` environment of the public repo, never
# repo-wide: only an approved run for a v* tag can read them (scripts/release/protect-repo.sh).
RELEASE_REPO="${JEFI_RELEASE_REPO:-algolab-cloud/jefi-mail-oss}"
RELEASE_ENV="${JEFI_RELEASE_ENV:-release}"

# set_secret NAME VALUE sets a secret of the release environment via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" --repo "$RELEASE_REPO" --env "$RELEASE_ENV" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s %s secret %s\n' "$GREEN" "$RESET" "$RELEASE_ENV" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name --repo $RELEASE_REPO --env $RELEASE_ENV)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Communication notifications let a mail banner show the sender's picture where
# the app icon goes (the app icon becomes a small badge), as Messages does. The
# capability needs a Developer ID provisioning profile for app.jefi.mail that
# grants com.apple.developer.usernotifications.communication. This wizard makes
# that profile, checks it, and stores it for the Release workflow. Wiring it
# into signing (embedding it and adding the entitlement) is a code change.

BUNDLE_ID="app.jefi.mail"
ENTITLEMENT="com.apple.developer.usernotifications.communication"
TOTAL_STAGES=4

banner "Jefi: sender pictures in notifications"

stage "Turn on Communication Notifications for $BUNDLE_ID"
say "Apple grants the capability per App ID, in your developer account."
open_url "https://developer.apple.com/account/resources/identifiers/list"
step "Find the App ID '$BUNDLE_ID' in the list and click it."
note "Not there? Click + → App IDs → App → Continue, Description 'Jefi',"
note "Bundle ID 'Explicit' = $BUNDLE_ID."
step "Under Capabilities, tick 'Communication Notifications'."
step "Click Save (or Continue → Register for a new App ID) and confirm."
pause "Press Enter once the capability shows as enabled."

stage "Create a Developer ID provisioning profile"
say "The profile is what carries the capability into the signed app."
open_url "https://developer.apple.com/account/resources/profiles/add"
step "Under Distribution, choose 'Developer ID' → Continue."
step "Profile type 'Mac', App ID '$BUNDLE_ID' → Continue."
step "Tick the Developer ID Application certificate you sign releases with → Continue."
CURRENT_IDENTITY=$(_existing MACOS_SIGNING_IDENTITY || true)
[[ -n "$CURRENT_IDENTITY" ]] && note "That's the one in $ENV_FILE: $CURRENT_IDENTITY"
step "Name it 'Jefi Developer ID' → Generate → Download."
pause "Press Enter once the .provisionprofile is downloaded."

stage "Check the profile"
say "Making sure it's for Jefi, grants the capability, and hasn't expired."
ask JEFI_PROVISIONING_PROFILE "Path to the profile [~/Downloads/Jefi_Developer_ID.provisionprofile]:"
[[ -z "$JEFI_PROVISIONING_PROFILE" ]] && JEFI_PROVISIONING_PROFILE="$HOME/Downloads/Jefi_Developer_ID.provisionprofile"
JEFI_PROVISIONING_PROFILE="${JEFI_PROVISIONING_PROFILE/#\~/$HOME}"
PROFILE_OK=false
DECODED=$(mktemp)
if [[ ! -f "$JEFI_PROVISIONING_PROFILE" ]]; then
  warn "no file at $JEFI_PROVISIONING_PROFILE"
elif ! security cms -D -i "$JEFI_PROVISIONING_PROFILE" > "$DECODED" 2>/dev/null; then
  warn "that file isn't a provisioning profile macOS can read."
else
  read_key() { /usr/libexec/PlistBuddy -c "Print :$1" "$DECODED" 2>/dev/null || true; }
  APP_IDENTIFIER=$(read_key "Entitlements:com.apple.application-identifier")
  [[ -z "$APP_IDENTIFIER" ]] && APP_IDENTIFIER=$(read_key "Entitlements:application-identifier")
  COMMUNICATION=$(read_key "Entitlements:$ENTITLEMENT")
  PROFILE_TEAM=$(read_key "TeamIdentifier:0")
  EXPIRES=$(plutil -extract ExpirationDate raw -o - "$DECODED" 2>/dev/null || true)
  EXPIRES_EPOCH=$(date -j -u -f "%Y-%m-%dT%H:%M:%SZ" "$EXPIRES" +%s 2>/dev/null || echo 0)
  EXPECTED_TEAM=$(_existing APPLE_TEAM_ID || true)
  PROFILE_OK=true
  if [[ "$APP_IDENTIFIER" == *".$BUNDLE_ID" ]]; then
    printf '  %s✓%s for %s\n' "$GREEN" "$RESET" "$APP_IDENTIFIER"
  else
    warn "it's for '$APP_IDENTIFIER', not $BUNDLE_ID"; PROFILE_OK=false
  fi
  if [[ "$COMMUNICATION" == "true" ]]; then
    printf '  %s✓%s grants Communication Notifications\n' "$GREEN" "$RESET"
  else
    warn "it doesn't grant Communication Notifications: enable it on the App ID, then regenerate the profile"; PROFILE_OK=false
  fi
  if [[ -z "$EXPECTED_TEAM" || "$PROFILE_TEAM" == "$EXPECTED_TEAM" ]]; then
    printf '  %s✓%s team %s\n' "$GREEN" "$RESET" "$PROFILE_TEAM"
  else
    warn "team $PROFILE_TEAM doesn't match APPLE_TEAM_ID $EXPECTED_TEAM in $ENV_FILE"; PROFILE_OK=false
  fi
  if (( EXPIRES_EPOCH > $(date +%s) )); then
    printf '  %s✓%s valid until %s\n' "$GREEN" "$RESET" "$EXPIRES"
  else
    warn "it has expired ($EXPIRES)"; PROFILE_OK=false
  fi
fi
rm -f "$DECODED"
if [[ "$PROFILE_OK" == true ]]; then
  # The path, for signing a release locally; the profile itself isn't committed.
  write_env JEFI_PROVISIONING_PROFILE "$JEFI_PROVISIONING_PROFILE"
else
  SKIPPED+=("a valid profile (fix what's flagged above and re-run this wizard)")
fi

stage "Store the profile for the Release workflow"
if [[ "$PROFILE_OK" != true ]]; then
  warn "skipping: the profile didn't pass its checks."
  pause
else
  say "CI signs the app, so it needs the profile too, as a GitHub secret."
  if confirm "Set MACOS_PROVISIONING_PROFILE_BASE64 on this repo?"; then
    set_secret MACOS_PROVISIONING_PROFILE_BASE64 "$(base64 -i "$JEFI_PROVISIONING_PROFILE" | tr -d '\n')"
  else
    SKIPPED+=("GitHub secret MACOS_PROVISIONING_PROFILE_BASE64 (base64 of the profile)")
  fi
fi
# ──────────────────────────────────────────────────────────────────────────

finish
note "Next: ask Claude to wire the profile into signing. sign.ts embeds it as"
note "Contents/embedded.provisionprofile and adds the entitlement; the notification"
note "helper sends mail banners as messages from the sender (INSendMessageIntent)."
note "Until that ships, banners keep the sender's picture as the thumbnail."
printf '\n'
